  let self_radius = pow(
    max(3.0 * self_mass_kg / (12.5663706 * max(self_rest_density, 1.0e-6)), 1.0e-30),
    1.0 / 3.0
  );
  let partner_radius = pow(
    max(3.0 * partner_mass_kg / (12.5663706 * max(partner_rest_density, 1.0e-6)), 1.0e-30),
    1.0 / 3.0
  );
